// Lookup once per trigger. Interpolate physical responses, not wavenumbers
// inside the shape equation, so a changing support cannot create a spurious
// exponentially growing mode. Outside the fitted frequency range hold the
// same endpoints as GetKalimbaMount. No per-sample work or mutable globals.
struct KalimbaMountShape {
    int lower = 0, upper = 1;
    double fraction = 0.0;
};
inline KalimbaMountShape GetKalimbaMountShape(double fundamentalHz) {
    const double hz = std::clamp(std::isfinite(fundamentalHz) ? fundamentalHz : 130.8127826502993,
        kKalimbaMountShapes[0].hz, kKalimbaMountShapes[11].hz);
    int upper = 1;
    while (upper < 11 && kKalimbaMountShapes[upper].hz < hz) ++upper;
    const double lo = kKalimbaMountShapes[upper-1].hz, hi = kKalimbaMountShapes[upper].hz;
    return {upper-1, upper, std::clamp(std::log(hz/lo)/std::log(hi/lo), 0.0, 1.0)};
}

inline double KalimbaMountedAverage(const KalimbaMountedMode& mode,
        double position, double width, bool curvature = false) {
    position = std::clamp(position, 0.0, 1.0);
    const double halfWidth = .5*std::clamp(width, 0.0, .25);
    const double lo = std::max(0.0, position-halfWidth), hi = std::min(1.0, position+halfWidth);
    const double centre = .5*(lo+hi), h = mode.beta*.5*(hi-lo);
    const double hyperbolicAverage = h > 1.e-3 ? (std::exp(h)-std::exp(-h))/(2*h)
        : 1+h*h/6+h*h*h*h/120;
    const double circularAverage = h > 1.e-8 ? std::sin(h)/h : 1;
    const double z = mode.beta*centre;
    const double hyperbolic = mode.ep*std::exp(mode.beta*(centre-1))+mode.em*std::exp(-z);
    const double circular = mode.cosine*std::cos(z)+mode.sine*std::sin(z);
    return mode.contactScale*(hyperbolic*hyperbolicAverage
        +(curvature ? -1 : 1)*circular*circularAverage)*(curvature ? mode.beta*mode.beta : 1);
}

inline double KalimbaMountedContactWeight(const KalimbaMountShape& shape,
        int mode, double position, double width) {
    mode = std::clamp(mode, 0, 7);
    const double lo = KalimbaMountedAverage(kKalimbaMountShapes[shape.lower].modes[mode], position, width);
    const double hi = KalimbaMountedAverage(kKalimbaMountShapes[shape.upper].modes[mode], position, width);
    return lo+shape.fraction*(hi-lo);
}

// The mass-normalized displacement itself, without the contact
// calibration above: for a voice that solves its own thumb contact against
// the tine's modal mass. Same normalization as KalimbaFullModeShape (both
// spans' integral of phi^2 = 1 in free-length units) and the same polarity.
inline double KalimbaMountedShape(const KalimbaMountShape& shape, int mode, double position) {
    mode = std::clamp(mode, 0, 7);
    position = std::clamp(position, 0.0, 1.0);
    const auto value = [position](const KalimbaMountedMode& d) {
        const double z = d.beta * position;
        return d.ep * std::exp(d.beta * (position - 1.0)) + d.em * std::exp(-z)
             + d.cosine * std::cos(z) + d.sine * std::sin(z);
    };
    const double lo = value(kKalimbaMountShapes[shape.lower].modes[mode]);
    const double hi = value(kKalimbaMountShapes[shape.upper].modes[mode]);
    return lo + shape.fraction * (hi - lo);
}

inline double KalimbaMountedRadiationSample(const KalimbaMountShape& shape, int mode, double position) {
    return KalimbaMountedContactWeight(shape, mode, position, 0.0);
}

// Mean square motion over the footprint: a contact crossing a node still
// damps moving material, while its signed force projection can cancel.
inline double KalimbaMountedContactParticipation(const KalimbaMountShape& shape,
        int mode, double position, double width) {
    position = std::clamp(position, 0.0, 1.0);
    const double halfWidth = .5*std::clamp(width, 0.0, .25);
    const double lo = std::max(0.0, position-halfWidth), hi = std::min(1.0, position+halfWidth);
    const double centre = .5*(lo+hi), offset = (hi-lo)*.288675134594813;
    const double a = KalimbaMountedContactWeight(shape, mode, centre-offset, 0);
    const double b = KalimbaMountedContactWeight(shape, mode, centre+offset, 0);
    return .5*(a*a+b*b);
}

// Curvature of the same eigenvector at the existing .06/.075 pickup patch.
// One common per-key gain preserves the established fundamental output; every
// upper weight remains the corresponding signed physical curvature ratio.
inline double KalimbaMountedStrainWeight(const KalimbaMountShape& shape, int mode) {
    mode = std::clamp(mode, 0, 7);
    const auto& lo = kKalimbaMountShapes[shape.lower];
    const auto& hi = kKalimbaMountShapes[shape.upper];
    const double a = lo.strainScale*KalimbaMountedAverage(lo.modes[mode], .06, .075, true);
    const double b = hi.strainScale*KalimbaMountedAverage(hi.modes[mode], .06, .075, true);
    return a+shape.fraction*(b-a);
}

