// END GENERATED MOUNT RADIATION

// Same 32 Gauss-Legendre nodes as ModalRadiation.h. Frozen float rounding is
// checked against the double analytical solution to < 2e-7 absolute error.
inline double KalimbaMountedRadiationNode(const KalimbaMountShape& shape, int mode, int point) {
    mode = std::clamp(mode, 0, 7);
    point = std::clamp(point, 0, 31);
    const double a = kKalimbaMountRadiation[shape.lower][mode][point];
    const double b = kKalimbaMountRadiation[shape.upper][mode][point];
    return a+shape.fraction*(b-a);
}

